  it('ML-DSA + Ed25519 - Generate/sign/verify', async function () {
    const digest = new Uint8Array(32).fill(1);
    const hashAlgo = openpgp.enums.hash.sha3_256;

    const { privateParams, publicParams } = await generateParams(openpgp.enums.publicKey.mldsa65Ed25519);
    const signature = await sign(openpgp.enums.publicKey.mldsa65Ed25519, hashAlgo, publicParams, privateParams, null, digest);
    const verified = await verify(openpgp.enums.publicKey.mldsa65Ed25519, hashAlgo, signature, publicParams, null, digest);
    expect(verified).to.be.true;
  });

  it('ML-DSA + Ed25519 - private key is correctly serialized using the seed instead of the expanded secret key material', async function () {
    const armoredKey = mldsaEd25519AndMlkemX25519PrivateKey;

    const { data: expectedBinaryKey } = await openpgp.unarmor(armoredKey);

    const privateKey = await openpgp.readKey({ armoredKey });
    expect(privateKey.write()).to.deep.equal(expectedBinaryKey);
  });

  it('ML-DSA + Ed25519 - Test vector', async function () {
    const privateKey = await openpgp.readKey({ armoredKey: mldsaEd25519AndMlkemX25519PrivateKey });
    const publicKey = await openpgp.readKey({ armoredKey: mldsaEd25519AndMlkemX25519PublicKey });

    // `getSigningKey()` internally verifies the ML-DSA binding sigs
    const signingKey1 = await privateKey.getSigningKey();
    const signingKey2 = await publicKey.getSigningKey();

    expect(signingKey1.getKeyID().equals(signingKey2.getKeyID())).to.be.true;
  });

