    const [sessionKey] = await openpgp.decryptSessionKeys({
      message: await openpgp.readMessage({ armoredMessage }),
      decryptionKeys: privateKey
    });
    expect(sessionKey.data).to.deep.equal(util.hexToUint8Array('0588ce40b038aac353d1cf8c67a674b412985105794821013ef154f786c4d89d'));

    const { data: decryptedData, signatures: [{ verified }] } = await openpgp.decrypt({
      message: await openpgp.readMessage({ armoredMessage }),
      decryptionKeys: privateKey,
      verificationKeys: publicKey
    });
    expect(decryptedData).to.equal('Testing\n');
    expect(await verified).to.be.true;
